<?php
namespace ProjectPress\Admin\Manager\ProjectManager;
use ProjectPress\Includes\Core\Defaults; use ProjectPress\Includes\Functions\Helpers\FormFieldHelper; use ProjectPress\Includes\Functions\Helpers\RequestHelper; use ProjectPress\Includes\Pages\Taxonomies; use ProjectPress\Includes\Project\Core\Project; use ProjectPress\Includes\Project\Core\ProjectClassificationRepository; use ProjectPress\Includes\Project\Core\ProjectFieldRepository; use ProjectPress\Includes\Project\Core\ProjectFieldService; use ProjectPress\Includes\Project\Core\ProjectPermissions; use ProjectPress\Includes\Project\ProjectManager as DomainProjectManager;
if(!defined('ABSPATH')){exit;}
final class Projects{
 private DomainProjectManager $manager; private ProjectClassificationRepository $classifications; private ProjectFieldRepository $fields; private ProjectFieldService $field_service;
 public function __construct(DomainProjectManager $manager){$this->manager=$manager;$this->classifications=new ProjectClassificationRepository();$this->fields=new ProjectFieldRepository();$this->field_service=new ProjectFieldService($this->fields,$manager->repository(),new ProjectPermissions());}
 public function render():void{$args=array('status'=>RequestHelper::get_key('status',''),'priority'=>RequestHelper::get_key('priority',''),'visibility'=>RequestHelper::get_key('visibility',''),'project_type'=>RequestHelper::get_integer('project_type',0),'project_category'=>RequestHelper::get_integer('project_category',0),'project_tag'=>RequestHelper::get_integer('project_tag',0),'project_label'=>RequestHelper::get_integer('project_label',0),'search'=>RequestHelper::get_text('s',''),'page'=>max(1,RequestHelper::get_integer('paged',1)),'per_page'=>20);$projects=$this->manager->query($args);$total=$this->manager->count($args);$pages=max(1,(int)ceil($total/$args['per_page']));$new=admin_url('admin.php?page=projectpress&group=project-manager&tab=new');?><div class="d-flex justify-content-between align-items-center mb-3"><p class="text-secondary mb-0"><?php printf(esc_html(_n('%d project found.','%d projects found.',$total,'projectpress')),$total);?></p><?php if(current_user_can('manage_options')||current_user_can('projectpress_projects_create')):?><a class="btn btn-primary" href="<?php echo esc_url($new);?>"><?php esc_html_e('New Project','projectpress');?></a><?php endif;?></div><form method="get" class="card card-body mb-3"><input type="hidden" name="page" value="projectpress"/><input type="hidden" name="group" value="project-manager"/><input type="hidden" name="tab" value="projects"/><div class="row g-2"><div class="col-md-4"><?php echo FormFieldHelper::text_input('s',$args['search'],array('placeholder'=>__('Search projects','projectpress')));?></div><div class="col-md-2"><?php echo FormFieldHelper::select('status',$this->choices(Defaults::project_statuses(),__('All statuses','projectpress')),$args['status']);?></div><div class="col-md-2"><?php echo FormFieldHelper::select('priority',$this->choices(Defaults::project_priorities(),__('All priorities','projectpress')),$args['priority']);?></div><div class="col-md-2"><?php echo FormFieldHelper::select('visibility',$this->choices(Defaults::project_visibilities(),__('All visibility','projectpress')),$args['visibility']);?></div><div class="col-md-2"><button class="btn btn-outline-primary w-100" type="submit"><?php esc_html_e('Filter','projectpress');?></button></div><?php foreach($this->filter_map() as $key=>$definition):?><div class="col-md-3"><?php echo FormFieldHelper::select($key,$this->term_choices($definition['taxonomy'],$definition['all']),$args[$key]);?></div><?php endforeach;?></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th><?php esc_html_e('Project','projectpress');?></th><th><?php esc_html_e('Key','projectpress');?></th><th><?php esc_html_e('Status','projectpress');?></th><th><?php esc_html_e('Priority','projectpress');?></th><th><?php esc_html_e('Visibility','projectpress');?></th></tr></thead><tbody><?php if(empty($projects)):?><tr><td colspan="5"><?php esc_html_e('No projects found.','projectpress');?></td></tr><?php endif;foreach($projects as $project):$edit=admin_url('admin.php?page=projectpress&group=project-manager&tab=edit&project_id='.$project->get_id());?><tr><td><a href="<?php echo esc_url($edit);?>"><?php echo esc_html($project->get_name());?></a></td><td><?php echo esc_html($project->get_key());?></td><td><?php echo esc_html($project->get_status());?></td><td><?php echo esc_html($project->get_priority());?></td><td><?php echo esc_html($project->get_visibility());?></td></tr><?php endforeach;?></tbody></table></div><?php if($pages>1):$base_args=array_filter(array('page'=>'projectpress','group'=>'project-manager','tab'=>'projects','s'=>$args['search'],'status'=>$args['status'],'priority'=>$args['priority'],'visibility'=>$args['visibility'],'project_type'=>$args['project_type'],'project_category'=>$args['project_category'],'project_tag'=>$args['project_tag'],'project_label'=>$args['project_label']),static fn($v)=>''!==$v&&0!==$v);?><nav><ul class="pagination"><?php for($page=1;$page<=$pages;$page++):?><li class="page-item <?php echo $page===$args['page']?'active':'';?>"><a class="page-link" href="<?php echo esc_url(add_query_arg(array_merge($base_args,array('paged'=>$page)),admin_url('admin.php')));?>"><?php echo esc_html((string)$page);?></a></li><?php endfor;?></ul></nav><?php endif;}
 public function render_form(int $project_id=0):void{$project=$project_id>0?$this->manager->find($project_id):null;if($project_id>0&&!$project){echo '<div class="notice notice-error"><p>'.esc_html__('Project not found.','projectpress').'</p></div>';return;}$data=$project?$project->to_array():array('name'=>'','description'=>'','status'=>Defaults::PROJECT_STATUS_DEFAULT,'priority'=>Defaults::PROJECT_PRIORITY_DEFAULT,'visibility'=>Defaults::PROJECT_VISIBILITY_DEFAULT);$field_values=$project?$this->fields->values($project_id):array();$global_fields=$this->fields->all(true);?><form class="card card-body" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_project_save"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project_id);?>"/><?php wp_nonce_field('projectpress_project_save');?><div class="mb-3"><?php echo FormFieldHelper::label('project-name',__('Name','projectpress'));echo FormFieldHelper::text_input('name',(string)$data['name'],array('id'=>'project-name','required'=>true));?></div><div class="mb-3"><?php echo FormFieldHelper::label('project-description',__('Description','projectpress'));echo FormFieldHelper::textarea('description',(string)$data['description'],array('id'=>'project-description','rows'=>5));?></div><div class="row g-3"><div class="col-md-4"><?php echo FormFieldHelper::select('status',array_combine(Defaults::project_statuses(),Defaults::project_statuses()),$data['status']);?></div><div class="col-md-4"><?php echo FormFieldHelper::select('priority',array_combine(Defaults::project_priorities(),Defaults::project_priorities()),$data['priority']);?></div><div class="col-md-4"><?php echo FormFieldHelper::select('visibility',array_combine(Defaults::project_visibilities(),Defaults::project_visibilities()),$data['visibility']);?></div></div><hr/><div class="row g-3"><?php foreach($this->classification_map() as $field=>$definition):$terms=$this->classifications->terms($definition['taxonomy']);$selected=$project?$this->classifications->assigned_term_ids($project_id,$definition['taxonomy']):array();?><div class="col-md-6"><label class="form-label"><?php echo esc_html($definition['label']);?></label><select class="form-select" name="<?php echo esc_attr($field);?>[]" multiple><?php foreach($terms as $term):?><option value="<?php echo esc_attr((string)$term->term_id);?>" <?php selected(in_array((int)$term->term_id,$selected,true));?>><?php echo esc_html($term->name);?></option><?php endforeach;?></select></div><?php endforeach;?></div><?php if($global_fields):?><hr/><h2 class="h5"><?php esc_html_e('Global Fields','projectpress');?></h2><div class="row g-3"><?php foreach($global_fields as $field):?><div class="col-md-6"><?php $this->render_global_field($field,$field_values[(int)$field['id']]??null);?></div><?php endforeach;?></div><?php endif;?><button class="btn btn-primary mt-3" type="submit"><?php echo esc_html($project?__('Update Project','projectpress'):__('Create Project','projectpress'));?></button></form><?php }
 public function handle_save():void{check_admin_referer('projectpress_project_save');$id=RequestHelper::integer($_POST,'project_id',0);$input=array('name'=>RequestHelper::text($_POST,'name',''),'description'=>RequestHelper::text($_POST,'description',''),'status'=>RequestHelper::key($_POST,'status',Defaults::PROJECT_STATUS_DEFAULT),'priority'=>RequestHelper::key($_POST,'priority',Defaults::PROJECT_PRIORITY_DEFAULT),'visibility'=>RequestHelper::key($_POST,'visibility',Defaults::PROJECT_VISIBILITY_DEFAULT));$result=$id>0?(($project=$this->manager->find($id))?$this->manager->service()->update($project,$input):new \WP_Error('projectpress_project_not_found',__('Project not found.','projectpress'))):$this->manager->create($input);if(!is_wp_error($result)&&$result instanceof Project){foreach($this->classification_map() as $field=>$definition){$this->classifications->assign($result->get_id(),$definition['taxonomy'],array_map('absint',RequestHelper::array($_POST,$field,array())));}$field_result=$this->field_service->save_project_values($result->get_id(),$this->project_field_input());if(is_wp_error($field_result))$result=$field_result;}$this->redirect_result($result);}
 public function handle_delete():void{check_admin_referer('projectpress_project_delete');$id=RequestHelper::integer($_POST,'project_id',0);$project=$this->manager->find($id);$this->redirect_result($project?$this->manager->service()->delete($project):new \WP_Error('projectpress_project_not_found',__('Project not found.','projectpress')));}
 public function handle_bulk():void{$this->redirect_result(new \WP_Error('projectpress_bulk_unavailable',__('Bulk deletion is disabled while the project archive lifecycle is implemented.','projectpress')));}
 private function render_global_field(array $field,?array $row):void{$id=(int)$field['id'];$name='project_fields['.$id.']';$html_id='project-field-'.$id;$type=(string)$field['field_type'];$value=$this->field_service->display_value($field,$row);$required=!empty($field['is_required']);?><label class="form-label" for="<?php echo esc_attr($html_id);?>"><?php echo esc_html($field['field_name']);?><?php if($required):?> <span class="text-danger">*</span><?php endif;?></label><?php if('textarea'===$type){?><textarea class="form-control" id="<?php echo esc_attr($html_id);?>" name="<?php echo esc_attr($name);?>" <?php echo $required?'required':'';?>><?php echo esc_textarea($value);?></textarea><?php }elseif('boolean'===$type){?><input type="hidden" name="<?php echo esc_attr($name);?>" value="0"/><input class="form-check-input" type="checkbox" id="<?php echo esc_attr($html_id);?>" name="<?php echo esc_attr($name);?>" value="1" <?php checked('1',$value);?>/><?php }else{$input_type=in_array($type,array('integer','decimal','user'),true)?'number':('email'===$type?'email':('url'===$type?'url':('date'===$type?'date':('datetime'===$type?'datetime-local':'text'))));$display='datetime'===$type&&$value?gmdate('Y-m-d\TH:i',strtotime($value)):('date'===$type&&$value?substr($value,0,10):$value);?><input class="form-control" type="<?php echo esc_attr($input_type);?>" id="<?php echo esc_attr($html_id);?>" name="<?php echo esc_attr($name);?>" value="<?php echo esc_attr($display);?>" <?php echo $required?'required':'';?>/><?php }if(!empty($field['field_description'])):?><div class="form-text"><?php echo esc_html($field['field_description']);?></div><?php endif;}
 private function choices(array $values,string $all):array{$choices=array(''=>$all);foreach($values as $value)$choices[$value]=ucwords(str_replace('_',' ',$value));return $choices;}
 private function term_choices(string $taxonomy,string $all):array{$choices=array(0=>$all);foreach($this->classifications->terms($taxonomy) as $term)$choices[(int)$term->term_id]=$term->name;return $choices;}
 private function filter_map():array{return array('project_type'=>array('taxonomy'=>Taxonomies::PROJECT_TYPE,'all'=>__('All types','projectpress')),'project_category'=>array('taxonomy'=>Taxonomies::PROJECT_CATEGORY,'all'=>__('All categories','projectpress')),'project_tag'=>array('taxonomy'=>Taxonomies::PROJECT_TAG,'all'=>__('All tags','projectpress')),'project_label'=>array('taxonomy'=>Taxonomies::PROJECT_LABEL,'all'=>__('All labels','projectpress')));}
 private function project_field_input():array{$raw=RequestHelper::array($_POST,'project_fields',array());$values=array();foreach($raw as $id=>$value){$id=absint($id);if($id>0)$values[$id]=is_array($value)?array_map('sanitize_text_field',$value):sanitize_text_field((string)$value);}return $values;}
 private function classification_map():array{return array('project_types'=>array('taxonomy'=>Taxonomies::PROJECT_TYPE,'label'=>__('Types','projectpress')),'project_categories'=>array('taxonomy'=>Taxonomies::PROJECT_CATEGORY,'label'=>__('Categories','projectpress')),'project_tags'=>array('taxonomy'=>Taxonomies::PROJECT_TAG,'label'=>__('Tags','projectpress')),'project_labels'=>array('taxonomy'=>Taxonomies::PROJECT_LABEL,'label'=>__('Labels','projectpress')));}
 private function redirect_result($result):void{$url=admin_url('admin.php?page=projectpress&group=project-manager&tab=projects');$url=is_wp_error($result)?add_query_arg('project_error',rawurlencode($result->get_error_message()),$url):add_query_arg('project_saved','1',$url);wp_safe_redirect($url);exit;}
}
